parameters.jsCode:
// Public counter: one visit per IP hash per 12 hours, plus the totals and the board from the
// payment branch. Both branches live in one workflow so they share workflow static data.
//
// WRITE AS RARELY AS POSSIBLE (2026-09-05). n8n loads workflow static data at the start of an
// execution and writes the WHOLE object back at the end, so two executions that overlap lose one
// of the two results ("last write wins" — n8n's own documentation says so). This branch runs on
// every page view; the payment branch runs for several seconds because of three Gmail calls.
// A visit that started after the payment's Code node and finished before its Gmail nodes used to
// write back the pre-payment snapshot: the payment vanished from the board and from the total,
// and its webhook id fell out of the "seen" ring so a Dodo retry could book it twice.
//
// Two defences, both needed. On the host: N8N_CONCURRENCY_PRODUCTION_LIMIT=1 serialises
// production executions, which removes the overlap itself (see README, "Concurrency"). Here:
// nothing is assigned unless it actually changed, and n8n only persists static data when an
// assignment happened. A repeat visitor inside the 12 hour window is now a pure read and cannot
// clobber anything, even if the host setting is ever lost.
//
// Note the shape of the code below: the new array is built first and assigned at the end. n8n
// detects a change by intercepting assignment on the static data object, not by watching a nested
// array, so push()-ing into store.seenIps in place would be both undetected and unsafe.
const crypto = require('crypto');

const store = $getWorkflowStaticData('global');
const headers = $input.first().json.headers || {};

// Behind a reverse proxy the client IP is the LAST entry the proxy appended.
const xff = String(headers['x-forwarded-for'] || '');
const ip = (xff.split(',').pop() || headers['x-real-ip'] || 'unknown').trim();
// Only a salted hash is kept, never the address itself (privacy policy).
// No fallback: the fallback string used to sit in a repository that is now public, and a
// known salt makes a SHA-256 of an IPv4 address enumerable in seconds, which would make the
// privacy policy's "only a salted hash is kept" untrue. Fail loudly like the webhook secret.
const salt = $env.OKRICH_IP_SALT;
if (!salt) throw new Error('OKRICH_IP_SALT is not set on the n8n host');
const hash = crypto.createHash('sha256').update(salt + ip).digest('hex').slice(0, 16);

const now = Date.now();
const WINDOW_MS = 12 * 60 * 60 * 1000;
const stored = Array.isArray(store.seenIps) ? store.seenIps : [];
const fresh = stored.filter((e) => now - e.t < WINDOW_MS);
const isNewVisitor = !fresh.some((e) => e.h === hash);
// Something expired: /privacy promises the hash is gone after twelve hours, so prune it even
// when this visitor is already known. That is the only write a repeat visitor can cause.
const pruned = fresh.length !== stored.length || !Array.isArray(store.seenIps);
if (isNewVisitor) {
  fresh.push({ h: hash, t: now });
  store.visitors = (Number(store.visitors) || 0) + 1;
}
if (isNewVisitor || pruned) {
  if (fresh.length > 5000) fresh.splice(0, fresh.length - 5000);
  store.seenIps = fresh;
}

const contributors = (Array.isArray(store.contributors) ? store.contributors : []).slice(0, 20);

return [{ json: { raised: Number(store.raised) || 0, visitors: Number(store.visitors) || 0, sales: Number(store.sales) || 0, contributors } }];

// Board maintenance. Reached ONLY through n8n's own UI (manual trigger), never over HTTP, so the
// n8n login is the authentication. That is deliberate: an admin webhook would mean a second public
// endpoint plus a second secret to keep, for something needed a handful of times a year.
//
// The board state lives in this workflow's static data, which is why this branch has to sit in the
// same workflow as the payment webhook rather than in an admin workflow of its own.
//
// Two modes, because the two real situations are different:
//   anonymise - the payment stands, only the displayed name is wrong or unwanted. Money keeps
//               counting toward the total; the entry shows as "anonymous".
//   remove    - the payment is gone (refund, chargeback). The entry disappears AND the raised
//               total is reduced, so the number on the page stays honest.
//   add       - the name was refused by the moderation and filed as anonymous, wrongly. Puts the
//               entry on the board WITHOUT touching the total, because an anonymous payment was
//               already counted in `raised` and `sales` when it arrived. Needs `amount` in the
//               "What to change" node. Added 2026-09-05: until then a false positive from
//               looksLikeAd() was unrecoverable, the owner never even learned the refused name.

const input = $input.first().json;
const target = String(input.name || '').trim();
const mode = String(input.mode || 'anonymise').trim().toLowerCase();

if (!target) {
  return [{ json: { ok: false, error: 'Set a name in the "What to change" node first.' } }];
}
if (mode !== 'anonymise' && mode !== 'remove' && mode !== 'add') {
  return [{ json: { ok: false, error: `mode must be "anonymise", "remove" or "add", got "${mode}"` } }];
}

const store = $getWorkflowStaticData('global');
store.contributors = Array.isArray(store.contributors) ? store.contributors : [];

const before = store.contributors.length;
const hits = store.contributors.filter(
  (c) => String(c.name).toLowerCase() === target.toLowerCase(),
);

// "add" is the only mode that works on a name which is deliberately NOT on the board yet.
if (mode === 'add') {
  const amount = Math.round((Number(input.amount) || 0) * 100) / 100;
  if (!(amount > 0)) {
    return [{ json: { ok: false, error: 'set a positive "amount" in the "What to change" node' } }];
  }
  store.contributors = Array.isArray(store.contributors) ? store.contributors : [];
  const existing = store.contributors.find(
    (c) => String(c.name).toLowerCase() === target.toLowerCase(),
  );
  if (existing) {
    existing.amount = Math.round(((Number(existing.amount) || 0) + amount) * 100) / 100;
  } else {
    store.contributors.push({ name: target, amount });
  }
  store.contributors.sort((a, b) => b.amount - a.amount);
  if (store.contributors.length > 50) store.contributors.length = 50;

  // The total is deliberately untouched: an anonymous payment already counted toward it.
  store.audit = Array.isArray(store.audit) ? store.audit : [];
  store.audit.push({ at: new Date().toISOString(), mode, target, entries: 1, raisedDelta: 0 });
  if (store.audit.length > 100) store.audit.splice(0, store.audit.length - 100);

  console.log(`board add: "${target}" ${amount} (total unchanged at ${store.raised})`);
  return [{ json: {
    ok: true, mode, target, entriesAffected: 1, raisedDelta: 0,
    contributorsBefore: before, contributorsAfter: store.contributors.length,
    raisedNow: Number(store.raised) || 0,
    board: store.contributors.map((c) => `${c.name} ${c.amount}`),
  } }];
}

if (hits.length === 0) {
  const names = store.contributors.map((c) => c.name);
  return [{ json: { ok: false, error: `no entry called "${target}"`, currentNames: names } }];
}

let raisedDelta = 0;
if (mode === 'remove') {
  raisedDelta = hits.reduce((sum, c) => sum + (Number(c.amount) || 0), 0);
  store.contributors = store.contributors.filter(
    (c) => String(c.name).toLowerCase() !== target.toLowerCase(),
  );
  store.raised = Math.max(0, Math.round(((Number(store.raised) || 0) - raisedDelta) * 100) / 100);
} else {
  for (const c of store.contributors) {
    if (String(c.name).toLowerCase() === target.toLowerCase()) c.name = 'anonymous';
  }
}

// A short audit trail, so a later "who removed that and when" has an answer.
store.audit = Array.isArray(store.audit) ? store.audit : [];
store.audit.push({ at: new Date().toISOString(), mode, target, entries: hits.length, raisedDelta });
if (store.audit.length > 100) store.audit.splice(0, store.audit.length - 100);

console.log(`board ${mode}: "${target}" x${hits.length}, raised delta ${raisedDelta}`);

return [
  {
    json: {
      ok: true,
      mode,
      target,
      entriesAffected: hits.length,
      raisedDelta,
      contributorsBefore: before,
      contributorsAfter: store.contributors.length,
      raisedNow: store.raised,
      board: store.contributors.map((c) => `${c.name} ${c.amount}`),
    },
  },
];

